      viewport: [innerWidth, innerHeight],
      overflow: document.documentElement.scrollWidth - document.documentElement.clientWidth,
      shell: [Math.round(shell.width), Math.round(shell.height)],
      canvas: [Math.round(canvas.width), Math.round(canvas.height)],
      hudBottom: Math.round(hud.bottom - shell.top),
      imagesComplete: [...document.images].every(image => image.complete && image.naturalWidth > 0),
    };
  }));
}
await page.setViewportSize({ width: 390, height: 844 });
await page.evaluate(() => window.__GAME_TEST__.resetGame());
await page.evaluate(() => window.__GAME_TEST__.spawnCustomer());
await page.waitForFunction(() => window.__GAME_TEST__.getState().customers[0]?.phase === 'waiting-stock', null, { timeout: 5000 });
const waitBeforeRefresh = await page.evaluate(() => window.__GAME_TEST__.getState().customers[0].patienceRemainingMs);
await page.reload({ waitUntil: 'networkidle' });
await page.waitForFunction(() => document.querySelector('#loading-overlay')?.hidden === true);
const waitAfterRefresh = await page.evaluate(() => window.__GAME_TEST__.getState().customers[0].patienceRemainingMs);
await page.evaluate(() => {
  const state = window.__GAME_TEST__.resetGame();
  state.player.x = 105;
  state.player.y = 175;
  state.player.interactionStationId = 'fishSource';
  state.player.interactionProgressMs = 500;
  localStorage.setItem('ai-game-factory:beach_fish_market_v4:save-v3', JSON.stringify(state));
});
await page.reload({ waitUntil: 'networkidle' });
await page.waitForFunction(() => document.querySelector('#loading-overlay')?.hidden === true);
await page.waitForFunction(() => window.__GAME_TEST__.getState().player.inventory.fish >= 1);
const productionAfterRefresh = await page.evaluate(() => window.__GAME_TEST__.getState().player.inventory.fish);
await page.screenshot({ path: 'artifacts/qa-390x844.png', fullPage: true });
const reducedPage = await browser.newPage({ viewport: { width: 390, height: 844 }, reducedMotion: 'reduce' });
await reducedPage.goto('http://127.0.0.1:4173/', { waitUntil: 'networkidle' });
await reducedPage.waitForFunction(() => document.querySelector('#loading-overlay')?.hidden === true);
const reducedMotion = await reducedPage.evaluate(() => matchMedia('(prefers-reduced-motion: reduce)').matches);
await browser.close();
console.log(JSON.stringify({ controls, layouts, waitBeforeRefresh, waitAfterRefresh, productionAfterRefresh, reducedMotion, consoleErrors }, null, 2));
NODE"

