 35	  return typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 36	}
 37	
 38	export function runRafMotion(spec: MotionSpec, frame: (progress: number) => void): Promise<void> {
 39	  if (spec.durationMs === 0) { frame(1); return Promise.resolve(); }
 40	  return new Promise((resolve) => {
 41	    let startedAt: number | undefined;
 42	    const tick = (timestamp: number): void => {
 43	      startedAt ??= timestamp;
 44	      const elapsedMs = timestamp - startedAt;
 45	      const sample = sampleMotion(spec, elapsedMs);
 46	      frame(sample.progress);
 47	      if (sample.done) resolve();
 48	      else requestAnimationFrame(tick);
 49	    };
 50	    requestAnimationFrame(tick);
 51	  });
 52	}
