 54	export function animateElement(element: HTMLElement, kind: Exclude<MotionKind, 'ambient'>, mode: 'enter' | 'pulse' = 'enter'): Promise<void> {
 55	  const spec = createMotionSpec(kind, prefersReducedMotion());
 56	  return runRafMotion(spec, (progress) => {
 57	    if (mode === 'pulse') {
 58	      const wave = Math.sin(progress * Math.PI);
 59	      element.style.transform = `translate3d(0,0,0) scale(${1 + wave * 0.075})`;
 60	      element.style.opacity = '1';
 61	    } else {
 62	      element.style.transform = `translate3d(0, ${(1 - progress) * -8}px, 0) scale(${0.985 + progress * 0.015})`;
 63	      element.style.opacity = String(progress);
 64	    }
 65	  }).finally(() => {
 66	    element.style.transform = 'translate3d(0,0,0) scale(1)';
 67	    element.style.opacity = '1';
 68	  });
 69	}
