 76	export function preloadImage(url: string): Promise<void> {
 77	  return new Promise((resolve, reject) => {
 78	    const image = new Image();
 79	    image.decoding = 'async';
 80	    image.onload = () => resolve();
 81	    image.onerror = () => reject(new Error(`Texture preload failed: ${url}`));
